/// <summary>
/// Base class for PricingAttribute table <c>CustDirectDebitMandate</c>.
/// </summary>
internal abstract class GUPPricingAttributeCustDirectDebitMandate extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{
}

Method.Source:
protected CustDirectDebitMandate getTableRecord(Common _pricingObject)
{
    SalesTable             salesTable = _pricingObject as SalesTable;
    CustDirectDebitMandate custDirectDebitMandate;

    if (salesTable)
    {
        custDirectDebitMandate = this.findByCustomer(salesTable.CustAccount);
    }

    return custDirectDebitMandate;
}

private CustDirectDebitMandate findByCustomer(CustAccount _custAccount)
{
    CustDirectDebitMandate custDirectDebitMandate;

    if (_custAccount)
    {
        select firstonly custDirectDebitMandate
            where custDirectDebitMandate.CustAccount == _custAccount;
    }

    return custDirectDebitMandate;
}

protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
{
    QueryBuildDataSource qbds, qbdsRoot;

    if (_qbdsMap && _qbdsMap.exists(tableStr(CustTable)))
    {
        qbdsRoot = _qbdsMap.lookup(tableStr(CustTable));
    }
    else
    {
        qbdsRoot = _query.addDataSource(tableNum(CustTable));

        if (_qbdsMap)
        {
            _qbdsMap.insert(tableStr(CustTable), qbdsRoot);
        }
    }

    if (_qbdsMap && _qbdsMap.exists(this.getQueryBuilderDatasourceIdentifier()))
    {
        qbds = _qbdsMap.lookup(this.getQueryBuilderDatasourceIdentifier());
    }
    else
    {
        qbds = qbdsRoot.addDataSource(tableNum(CustDirectDebitMandate));
        qbds.addLink(fieldNum(CustTable, AccountNum), fieldNum(CustDirectDebitMandate, CustAccount));
        qbds.joinMode(JoinMode::ExistsJoin);

        if (_qbdsMap)
        {
            _qbdsMap.insert(this.getQueryBuilderDatasourceIdentifier(), qbds);
        }
    }

    return qbds;
}

public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
{
    QueryBuildDataSource qbds;

    qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
    this.setQueryBuildDatasourceRange(qbds, _value);

    return _query;
}
